import * as React from "react";
import { useUserContext } from '../context/UserContext';
import { UserProfile, Product } from '../utils/types';
import { SUPPORTED_LANGUAGES } from '../data/constants';
import toast from 'react-hot-toast';
import ToggleSwitch from '@/components/ui/ToggleSwitch';
import InfoModal from '@/components/InfoModal';

interface ProfileModalProps {
  isOpen: boolean;
  onClose: () => void;
}

const ProfileModal: React.FC<ProfileModalProps> = ({ isOpen, onClose }) => {
  const { userProfile, updateUserProfile } = useUserContext();
  const [localProfile, setLocalProfile] = React.useState<UserProfile>(userProfile);

  React.useEffect(() => {
    // When the modal is opened, reset the local state to match the current user profile.
    // This ensures that each time the modal is opened, it starts with fresh, up-to-date data.
    // We intentionally omit `userProfile` from the dependency array because we *only* want
    // this effect to run when the modal's `isOpen` state changes from false to true.
    // If we included `userProfile`, any external update to the profile (like changing the resolution
    // in the footer) would overwrite the user's edits inside the modal.
    if (isOpen) {
      setLocalProfile(userProfile);
    }
  }, [isOpen]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    const isCheckbox = type === 'checkbox';
    const checkedValue = (e.target as HTMLInputElement).checked;

    setLocalProfile(prev => ({
      ...prev,
      [name]: isCheckbox ? checkedValue : value
    }));
  };

  const handleSave = () => {
    if (JSON.stringify(localProfile, null, 2) !== JSON.stringify(userProfile, null, 2)) {
        updateUserProfile(localProfile);
        const nameToDisplay = localProfile.name || "Profile";
        toast.success(`${nameToDisplay} saved!`);
    }
    onClose();
  };

  const parseCsvToProducts = (csvText: string): Product[] => {
    const lines = csvText.trim().split('\n').filter(line => line.trim() !== '');
    if (lines.length < 2) throw new Error('CSV file must have a header row and at least one data row.');

    const headerLine = lines.shift() || '';
    const header = headerLine.split(',').map(h => h.trim().toLowerCase());

    const requiredHeaders = ['sku', 'description', 'category'];
    if (!requiredHeaders.every(h => header.includes(h))) {
        throw new Error('CSV is missing required headers: SKU, Description, Category.');
    }

    return lines.map((line): Product | null => {
        const row: { [key: string]: string } = {};
        // Regex to split by comma but ignore commas inside double quotes
        const values = line.match(/(".*?"|[^",]+)(?=\s*,|\s*$)/g) || [];

        header.forEach((key, i) => {
            let value = values[i] || '';
            // Remove quotes if present
            if (value.startsWith('"') && value.endsWith('"')) {
                value = value.slice(1, -1);
            }
            row[key] = value.trim();
        });

        if (!row.sku || !row.description) return null;

        return {
            sku: row.sku,
            name: row.description,
            category: row.category || 'Uncategorized',
            description: row.description || '',
            tags: [],
        };
    }).filter((p): p is Product => p !== null);
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
      const file = event.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = (e) => {
          const text = e.target?.result as string;
          try {
              const products = parseCsvToProducts(text);
              setLocalProfile(prev => ({ ...prev, customProductDatabase: products }));
              toast.success(`${products.length} products imported successfully!`);
          } catch (error) {
              toast.error(error instanceof Error ? error.message : 'Failed to parse CSV.');
          }
      };
      reader.readAsText(file);
      // Reset file input to allow re-upload of the same file
      event.target.value = '';
  };

  const handleRemoveCustomDb = () => {
    setLocalProfile(prev => {
        const { customProductDatabase, ...rest } = prev;
        return rest;
    });
    toast.success('Custom product database removed.');
  };

  const footer = (
    <>
      <button onClick={onClose} className="btn btn-secondary">Cancel</button>
      <button onClick={handleSave} className="btn btn-primary">Save Changes</button>
    </>
  );

  return (
    <InfoModal isOpen={isOpen} onClose={onClose} className="max-w-4xl" title="Pilot Profile & Settings" footer={footer}>
      <div className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
               <div>
                  <label htmlFor="profile-name" className="block text-sm font-medium">Name</label>
                  <input type="text" id="profile-name" name="name" value={localProfile.name} onChange={handleChange} className="w-full p-2 border border-border-color rounded-md bg-input-bg mt-1" />
              </div>
               <div>
                  <label htmlFor="profile-company" className="block text-sm font-medium">Company</label>
                  <input type="text" id="profile-company" name="company" value={localProfile.company} onChange={handleChange} className="w-full p-2 border border-border-color rounded-md bg-input-bg mt-1" />
              </div>
              <div>
                  <label htmlFor="profile-language" className="block text-sm font-medium">Language</label>
                  <select id="profile-language" name="language" value={localProfile.language} onChange={handleChange} className="w-full p-2 border border-border-color rounded-md bg-input-bg mt-1">
                      {SUPPORTED_LANGUAGES.map(lang => <option key={lang.code} value={lang.code}>{lang.name}</option>)}
                  </select>
              </div>
              <div>
                  <label htmlFor="profile-unit-system" className="block text-sm font-medium">Unit System</label>
                  <select id="profile-unit-system" name="unitSystem" value={localProfile.unitSystem} onChange={handleChange} className="w-full p-2 border border-border-color rounded-md bg-input-bg mt-1">
                      <option value="metric">Metric (meters)</option>
                      <option value="imperial">Imperial (feet)</option>
                  </select>
              </div>
          </div>
          <div>
              <h3 className="text-lg font-semibold mb-2">Appearance</h3>
              <div className="flex items-center justify-between p-3 bg-background rounded-md border border-border-color">
                  <label htmlFor="show-background" className="text-sm font-medium">Show Background Image Carousel</label>
                  <ToggleSwitch
                      checked={localProfile.showBackground}
                      onChange={(isChecked) => setLocalProfile(p => ({ ...p, showBackground: isChecked }))} />
              </div>
          </div>
          <div>
              <h3 className="text-lg font-semibold mb-2">Custom Product Database</h3>
              <div className="p-3 bg-background rounded-md border border-border-color">
                  <label htmlFor="product-db-upload" className="block text-sm font-medium">Upload Product CSV</label>
                  <p className="text-xs text-text-secondary mb-2">
                      Import a custom product list. New projects will use this database instead of the default.
                      Required columns: <strong>SKU, Description, Category</strong>.
                  </p>
                  <input 
                      type="file" 
                      id="product-db-upload" 
                      accept=".csv" 
                      onChange={handleFileChange} 
                      className="text-sm file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-accent-bg-subtle file:text-accent hover:file:bg-accent-bg-very-subtle"
                  />
                  {localProfile.customProductDatabase && (
                      <div className="mt-2 text-sm text-green-600">
                          <p>
                              Custom database with {localProfile.customProductDatabase.length} products is active. 
                              <button onClick={handleRemoveCustomDb} className="ml-2 text-red-500 underline text-xs">Remove</button>
                          </p>
                      </div>
                  )}
              </div>
          </div>
      </div>
    </InfoModal>
  );
};

export default ProfileModal;

import * as React from "react";
import type { CompetitorItem, MatchReason, MatchResult, Product } from "./types";
import { WYRESTORM_PRODUCTS } from "./competitorDataset";

/** Normalise SKUs to compare: uppercase, strip spaces, dashes, underscores, slashes */
export function normaliseSku(s: string): string {
  return (s || "")
    .toUpperCase()
    .replace(/[\s\-_\/\\]+/g, "")
    .replace(/[^\w]/g, "");
}

/** Normalise feature tokens */
function normFeat(xs?: string[]): string[] {
  return (xs || []).map(x => (x || "").toLowerCase().trim()).filter(Boolean);
}

/** Map resolution label to a comparable rank */
function resRank(r?: string): number {
  switch ((r || "").toUpperCase()) {
    case "1080P": return 1;
    case "4K30":  return 2;
    case "4K60":  return 3;
    case "8K":    return 4;
    default:      return 0;
  }
}

function scoreExactSku(c: CompetitorItem, p: Product): MatchReason {
  // Not usually exact across brands, but supports same-SKU within WyreStorm if used.
  const s = normaliseSku(c.sku);
  const t = normaliseSku(p.sku);
  const hit = s === t ? 1 : 0;
  return { key: "exactSku", score: hit * 0.25, text: hit ? "Exact SKU match" : "No exact SKU match" };
}

function scoreCategory(c: CompetitorItem, p: Product): MatchReason {
  const a = (c.category || "").toLowerCase();
  const b = (p.category || "").toLowerCase();
  const hit = a && b && a === b ? 1 : 0;
  return { key: "category", score: hit * 0.20, text: hit ? `Category match: ${a}` : "Category differs/unknown" };
}

function scoreRole(c: CompetitorItem, p: Product): MatchReason {
  const a = (c.role || "").toLowerCase();
  const b = (p.role || "").toLowerCase();
  const hit = a && b && a === b ? 1 : 0;
  return { key: "role", score: hit * 0.20, text: hit ? `Role match: ${a}` : "Role differs/unknown" };
}

function scoreResolution(c: CompetitorItem, p: Product): MatchReason {
  const cr = resRank(c.video?.maxResolution);
  const pr = resRank(p.video?.maxResolution);
  if (!cr || !pr) return { key: "resolution", score: 0.05, text: "Resolution unknown (light weight)" };
  const diff = Math.abs(cr - pr);
  const hit = diff === 0 ? 1 : diff === 1 ? 0.6 : 0.2;
  return { key: "resolution", score: hit * 0.15, text: `Resolution closeness: competitor ${c.video?.maxResolution} vs WyreStorm ${p.video?.maxResolution}` };
}

function scoreBandwidth(c: CompetitorItem, p: Product): MatchReason {
  const cb = c.video?.bandwidthGbps || 0;
  const pb = p.video?.bandwidthGbps || 0;
  if (!cb || !pb) return { key: "bandwidth", score: 0.05, text: "Bandwidth unknown (light weight)" };
  const diff = Math.abs(cb - pb);
  const hit = diff <= 1 ? 1 : diff <= 3 ? 0.6 : 0.2;
  return { key: "bandwidth", score: hit * 0.10, text: `Bandwidth closeness: competitor ${cb}Gbps vs WyreStorm ${pb}Gbps` };
}

function scoreFeatures(c: CompetitorItem, p: Product): MatchReason {
  const cf = new Set(normFeat(c.features));
  const pf = new Set(normFeat(p.features));
  if (cf.size === 0 || pf.size === 0) return { key: "features", score: 0.05, text: "Features sparse/unknown (light weight)" };

  let common = 0;
  cf.forEach(x => { if (pf.has(x)) common++; });
  const denom = Math.max(cf.size, pf.size);
  const ratio = denom ? common / denom : 0;
  return { key: "features", score: ratio * 0.10, text: `Feature overlap: ${common}/${denom}` };
}

function scoreFamilyHint(c: CompetitorItem, p: Product): MatchReason {
  const a = (c.familyHint || "").toLowerCase();
  const b = (p.family || "").toLowerCase();
  const hit = a && b && a === b ? 1 : 0;
  return { key: "family", score: hit * 0.10, text: hit ? `Family hint match: ${c.familyHint}` : "No family hint match" };
}

function clamp01(x: number): number {
  return Math.max(0, Math.min(1, x));
}

export type MatchOptions = {
  topN?: number;
  products?: Product[]; // If provided, use your real product catalog here
};

export function matchCompetitor(competitor: CompetitorItem, opts: MatchOptions = {}): MatchResult[] {
  const topN = opts.topN ?? 5;
  const products = (opts.products && opts.products.length ? opts.products : WYRESTORM_PRODUCTS);

  const results: MatchResult[] = products.map(p => {
    const reasons: MatchReason[] = [
      scoreExactSku(competitor, p),
      scoreCategory(competitor, p),
      scoreRole(competitor, p),
      scoreResolution(competitor, p),
      scoreBandwidth(competitor, p),
      scoreFeatures(competitor, p),
      scoreFamilyHint(competitor, p)
    ];

    const score = clamp01(reasons.reduce((a, r) => a + r.score, 0));
    const percent = Math.round(score * 100);

    return { competitor, product: p, score, percent, reasons };
  });

  return results
    .sort((a, b) => b.score - a.score)
    .slice(0, topN);
}

/** Convenience: input "Brand SKU" or just SKU; parses a minimal CompetitorItem */
export function parseCompetitorInput(input: string): CompetitorItem {
  const raw = (input || "").trim();
  if (!raw) return { brand: "Unknown", sku: "" };

  // crude parse: first token brand if it looks alphabetic; rest sku
  const parts = raw.split(/\s+/).filter(Boolean);
  if (parts.length >= 2 && /^[A-Za-z]{2,}$/.test(parts[0])) {
    return { brand: parts[0], sku: parts.slice(1).join(" ") };
  }
  return { brand: "Unknown", sku: raw };
}
export function searchCompetitors(_query: string): CompetitorItem[] {
  return [];
}
export function matchToCatalog(competitor: CompetitorItem, opts: MatchOptions = {}): MatchResult[] {
  return matchCompetitor(competitor, opts);
}
export function canAddSku(sku: string): boolean {
  return !!sku && !!sku.trim();
}

import * as React from "react";

import InfoModal from './InfoModal';
import { RoomData, DesignTier, Product } from '../utils/types';
import toast from 'react-hot-toast';

interface BulkOperationsModalProps {
  isOpen: boolean;
  onClose: () => void;
  rooms: RoomData[];
  onApplyChanges: (roomIds: string[], changes: Partial<RoomData>) => void;
}

const BulkOperationsModal: React.FC<BulkOperationsModalProps> = ({
  isOpen,
  onClose,
  rooms,
  onApplyChanges,
}) => {
  const [selectedRooms, setSelectedRooms] = React.useState<Set<string>>(new Set());
  const [operation, setOperation] = React.useState<'tier' | 'equipment' | 'feature'>('tier');
  const [newTier, setNewTier] = React.useState<DesignTier>('Silver');

  const toggleRoom = (roomId: string) => {
    setSelectedRooms(prev => {
      const newSet = new Set(prev);
      if (newSet.has(roomId)) {
        newSet.delete(roomId);
      } else {
        newSet.add(roomId);
      }
      return newSet;
    });
  };

  const selectAll = () => {
    setSelectedRooms(new Set(rooms.map(r => r.id)));
  };

  const deselectAll = () => {
    setSelectedRooms(new Set());
  };

  const handleApply = () => {
    if (selectedRooms.size === 0) {
      toast.error('Please select at least one room');
      return;
    }

    const changes: Partial<RoomData> = {};

    switch (operation) {
      case 'tier':
        changes.designTier = newTier;
        break;
      // Add more operations here
    }

    onApplyChanges(Array.from(selectedRooms), changes);
    toast.success(`Applied changes to ${selectedRooms.size} room(s)`);
    onClose();
  };

  return (
    <InfoModal
      isOpen={isOpen}
      onClose={onClose}
      title="Bulk Room Operations"
      className="max-w-4xl"
      footer={
        <>
          <button onClick={onClose} className="btn btn-secondary">
            Cancel
          </button>
          <button
            onClick={handleApply}
            className="btn btn-primary"
            disabled={selectedRooms.size === 0}
          >
            Apply to {selectedRooms.size} Room(s)
          </button>
        </>
      }
    >
      <div className="space-y-6">
        {/* Room Selection */}
        <div>
          <div className="flex justify-between items-center mb-3">
            <h3 className="text-lg font-bold">Select Rooms</h3>
            <div className="flex gap-2">
              <button onClick={selectAll} className="text-sm text-accent hover:underline">
                Select All
              </button>
              <button onClick={deselectAll} className="text-sm text-accent hover:underline">
                Deselect All
              </button>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-2 max-h-140 overflow-y-auto custom-scrollbar p-2 border border-border-color rounded-lg">
            {rooms.map(room => (
              <label
                key={room.id}
                className="flex items-center gap-3 p-3 rounded-md hover:bg-background-secondary cursor-pointer"
              >
                <input
                  type="checkbox"
                  checked={selectedRooms.has(room.id)}
                  onChange={() => toggleRoom(room.id)}
                  className="h-4 w-4"
                />
                <div className="flex-1">
                  <p className="font-semibold text-text-primary">{room.roomName}</p>
                  <p className="text-sm text-text-secondary">
                    {room.roomType} â€¢ {room.designTier}
                  </p>
                </div>
              </label>
            ))}
          </div>
        </div>

        {/* Operation Selection */}
        <div>
          <h3 className="text-lg font-bold mb-3">Select Operation</h3>
          <div className="space-y-3">
            <label className="flex items-center gap-3 p-3 rounded-md border border-border-color hover:bg-background-secondary cursor-pointer">
              <input
                type="radio"
                name="operation"
                value="tier"
                checked={operation === 'tier'}
                onChange={(e) => setOperation(e.target.value as any)}
                className="h-4 w-4"
              />
              <div className="flex-1">
                <p className="font-semibold">Change Design Tier</p>
                <p className="text-sm text-text-secondary">
                  Update the quality/budget tier for selected rooms
                </p>
              </div>
            </label>

            <label className="flex items-center gap-3 p-3 rounded-md border border-border-color hover:bg-background-secondary cursor-pointer opacity-50">
              <input
                type="radio"
                name="operation"
                value="equipment"
                disabled
                className="h-4 w-4"
              />
              <div className="flex-1">
                <p className="font-semibold">Add Equipment</p>
                <p className="text-sm text-text-secondary">
                  Add the same equipment to multiple rooms (Coming soon)
                </p>
              </div>
            </label>

            <label className="flex items-center gap-3 p-3 rounded-md border border-border-color hover:bg-background-secondary cursor-pointer opacity-50">
              <input
                type="radio"
                name="operation"
                value="feature"
                disabled
                className="h-4 w-4"
              />
              <div className="flex-1">
                <p className="font-semibold">Toggle Features</p>
                <p className="text-sm text-text-secondary">
                  Enable/disable features across rooms (Coming soon)
                </p>
              </div>
            </label>
          </div>
        </div>

        {/* Operation Parameters */}
        {operation === 'tier' && (
          <div>
            <h3 className="text-lg font-bold mb-3">New Design Tier</h3>
            <select
              value={newTier}
              onChange={(e) => setNewTier(e.target.value as DesignTier)}
              className="w-full p-3 border border-border-color rounded-lg bg-input-bg"
            >
              <option value="Bronze">Bronze - Budget-friendly</option>
              <option value="Silver">Silver - Mid-range quality</option>
              <option value="Gold">Gold - Premium solution</option>
            </select>
          </div>
        )}

        {/* Preview */}
        {selectedRooms.size > 0 && (
          <div className="p-4 bg-accent-bg-subtle border border-accent rounded-lg">
            <p className="font-semibold text-accent">Preview Changes</p>
            <p className="text-sm text-text-secondary mt-1">
              {selectedRooms.size} room(s) will be updated to{' '}
              <span className="font-semibold">{newTier}</span> tier
            </p>
          </div>
        )}
      </div>
    </InfoModal>
  );
};

export default BulkOperationsModal;

import * as React from "react";

import { ProjectData, RoomData, ManuallyAddedEquipment } from '../utils/types';

interface CostSummaryDisplayProps {
    projectData: ProjectData;
    showDetails?: boolean;
    markup?: number; // Percentage markup (e.g., 25 for 25%)
    laborRates?: {
        role: string;
        ratePerHour: number;
        estimatedHours?: number;
    }[];
}

interface CostBreakdown {
    equipmentCost: number;
    laborCost: number;
    ancillaryCosts: number;
    subtotal: number;
    markup: number;
    tax: number;
    total: number;
    roomBreakdown: {
        roomId: string;
        roomName: string;
        equipmentCost: number;
        estimatedLaborHours: number;
        laborCost: number;
    }[];
}

const CostSummaryDisplay: React.FC<CostSummaryDisplayProps> = ({
    projectData,
    showDetails = true,
    markup = 20,
    laborRates = []
}) => {
    const costBreakdown = React.useMemo<CostBreakdown>(() => {
        let totalEquipmentCost = 0;
        let totalLaborCost = 0;
        const roomBreakdown: CostBreakdown['roomBreakdown'] = [];

        // Calculate costs per room
        projectData.rooms.forEach(room => {
            let roomEquipmentCost = 0;

            // Sum up equipment costs
            room.manuallyAddedEquipment.forEach(equipment => {
                const unitPrice = equipment.msrp || 0;
                roomEquipmentCost += unitPrice * equipment.quantity;
            });

            // Estimate labor hours based on room complexity
            const estimatedLaborHours = estimateLaborHours(room);
            
            // Calculate labor cost
            const averageLaborRate = laborRates.length > 0
                ? laborRates.reduce((sum, rate) => sum + rate.ratePerHour, 0) / laborRates.length
                : 75; // Default $75/hour
            
            const roomLaborCost = estimatedLaborHours * averageLaborRate;

            totalEquipmentCost += roomEquipmentCost;
            totalLaborCost += roomLaborCost;

            roomBreakdown.push({
                roomId: room.id,
                roomName: room.roomName,
                equipmentCost: roomEquipmentCost,
                estimatedLaborHours,
                laborCost: roomLaborCost,
            });
        });

        // Calculate ancillary costs (cabling, conduit, misc materials)
        const ancillaryCosts = totalEquipmentCost * 0.15; // 15% of equipment cost

        const subtotal = totalEquipmentCost + totalLaborCost + ancillaryCosts;
        const markupAmount = subtotal * (markup / 100);
        const taxAmount = (subtotal + markupAmount) * 0.08; // Assuming 8% tax
        const total = subtotal + markupAmount + taxAmount;

        return {
            equipmentCost: totalEquipmentCost,
            laborCost: totalLaborCost,
            ancillaryCosts,
            subtotal,
            markup: markupAmount,
            tax: taxAmount,
            total,
            roomBreakdown,
        };
    }, [projectData, markup, laborRates]);

    const formatCurrency = (amount: number): string => {
        return new Intl.NumberFormat('en-US', {
            style: 'currency',
            currency: 'USD',
        }).format(amount);
    };

    const estimateLaborHours = (room: RoomData): number => {
        // Base hours
        let hours = 8; // Minimum for any room

        // Add hours based on equipment count
        hours += room.manuallyAddedEquipment.length * 1.5;

        // Add hours for display installation
        hours += room.displayCount * 2;

        // Add hours for video wall
        if (room.videoWallConfig) {
            const displays = room.videoWallConfig.layout.rows * room.videoWallConfig.layout.cols;
            hours += displays * 3; // Video walls take longer
        }

        // Add hours for audio system
        if (room.audioSystemDetails) {
            hours += 4;
            if ((room.audioSystemDetails as any).ceilingMics > 0) hours += 2;
            if ((room.audioSystemDetails as any).talkbackMics > 0) hours += 2;
        }

        // Add hours for I/O points
        hours += room.ioRequirements.length * 0.5;

        // Tier multiplier (higher tiers take more configuration time)
        const tierMultiplier = {
            Bronze: 1.0,
            Silver: 1.2,
            Gold: 1.4,
        }[room.designTier];

        return Math.ceil(hours * tierMultiplier);
    };

    return (
        <div className="bg-background-secondary\ rounded-xl\ border\ border-border-color\ overflow-hidden">
            <div className="bg-gradient-to-r\ from-accent\ to-accent-dark\ p-6\ text-white">
                <h2 className="text-2xl\ font-bold\ mb-2">Project Cost Summary</h2>
                <p className="text-white/80">{projectData.projectName}</p>
            </div>

            <div className="p-6\ space-y-6">
                {/* High-level summary */}
                <div className="grid\ grid-cols-2\ md:grid-cols-4\ gap-4">
                    <div className="bg-background-secondary-subtle\ p-4\ rounded-lg">
                        <p className="text-xs\ text-text-secondary\ uppercase\ mb-1">Equipment</p>
                        <p className="text-2xl\ font-bold">{formatCurrency(costBreakdown.equipmentCost)}</p>
                    </div>
                    <div className="bg-background-secondary-subtle\ p-4\ rounded-lg">
