export default DesignTierSelector;

import * as React from "react";
import { useUserContext } from '../../../context/UserContext';
import { RoomWizardAnswers } from '../../../utils/types';

interface RoomSpecsInputsProps {
  answers: RoomWizardAnswers;
  updateAnswers: (newAnswers: Partial<RoomWizardAnswers>) => void;
  errors: Record<string, string>;
}

const METER_TO_FEET = 3.28084;

const RoomSpecsInputs: React.FC<RoomSpecsInputsProps> = ({ answers, updateAnswers, errors }) => {
  const { userProfile } = useUserContext();
  const isImperial = userProfile.unitSystem === 'imperial';

  const toDisplay = (meters: number) => (isImperial ? (meters * METER_TO_FEET).toFixed(1) : String(meters));
  const fromDisplay = (value: string) => {
    const num = parseFloat(value) || 0;
    return isImperial ? num / METER_TO_FEET : num;
  };

  const [localLength, setLocalLength] = React.useState(() => toDisplay(answers.dimensions.length));
  const [localWidth, setLocalWidth] = React.useState(() => toDisplay(answers.dimensions.width));
  const [localHeight, setLocalHeight] = React.useState(() => toDisplay(answers.dimensions.height));

  React.useEffect(() => {
    setLocalLength(toDisplay(answers.dimensions.length));
    setLocalWidth(toDisplay(answers.dimensions.width));
    setLocalHeight(toDisplay(answers.dimensions.height));
  }, [answers.dimensions, isImperial]);

  const handleBlur = (field: 'length' | 'width' | 'height', value: string) => {
    updateAnswers({ dimensions: { ...answers.dimensions, [field]: fromDisplay(value) } });
  };
  
  const unitLabel = isImperial ? 'ft' : 'm';

  return (
    <div className="grid\ grid-cols-1\ md:grid-cols-2\ lg:grid-cols-4\ gap-6">
      <div>
        <label htmlFor="room-length" className="block\ text-sm\ font-medium\ text-text-secondary">Length ({unitLabel})</label>
        <input
          type="number"
          step="0.1"
          id="room-length"
          value={localLength}
          onChange={(e) => setLocalLength(e.target.value)}
          onBlur={(e) => handleBlur('length', e.target.value)}
          className={`w-full p-2 border rounded-md bg-input-bg mt-1 ${errors.length ? 'border-destructive' : 'border-border-color'}`}
        />
        {errors.length && <p className="text-destructive\ text-sm\ mt-1">{errors.length}</p>}
      </div>
      <div>
        <label htmlFor="room-width" className="block\ text-sm\ font-medium\ text-text-secondary">Width ({unitLabel})</label>
        <input
          type="number"
          step="0.1"
          id="room-width"
          value={localWidth}
          onChange={(e) => setLocalWidth(e.target.value)}
          onBlur={(e) => handleBlur('width', e.target.value)}
          className={`w-full p-2 border rounded-md bg-input-bg mt-1 ${errors.width ? 'border-destructive' : 'border-border-color'}`}
        />
        {errors.width && <p className="text-destructive\ text-sm\ mt-1">{errors.width}</p>}
      </div>
      <div>
        <label htmlFor="room-height" className="block\ text-sm\ font-medium\ text-text-secondary">Height ({unitLabel})</label>
        <input
          type="number"
          step="0.1"
          id="room-height"
          value={localHeight}
          onChange={(e) => setLocalHeight(e.target.value)}
          onBlur={(e) => handleBlur('height', e.target.value)}
          className={`w-full p-2 border rounded-md bg-input-bg mt-1 ${errors.height ? 'border-destructive' : 'border-border-color'}`}
        />
        {errors.height && <p className="text-destructive\ text-sm\ mt-1">{errors.height}</p>}
      </div>
      <div>
        <label htmlFor="room-participants" className="block\ text-sm\ font-medium\ text-text-secondary">Max Participants</label>
        <input
          type="number"
          id="room-participants"
          value={answers.maxParticipants}
          onChange={(e) => updateAnswers({ maxParticipants: Number(e.target.value) })}
          className={`w-full p-2 border rounded-md bg-input-bg mt-1 ${errors.maxParticipants ? 'border-destructive' : 'border-border-color'}`}
        />
        {errors.maxParticipants && <p className="text-destructive\ text-sm\ mt-1">{errors.maxParticipants}</p>}
      </div>
    </div>
  );
};

export default RoomSpecsInputs;

import * as React from "react";
import { IOPoint } from '../../../utils/types';
import { useUserContext } from '../../../context/UserContext';
import { CONNECTION_TYPES, TRANSPORT_TYPES, LOCATION_TYPES } from '../../../data/wizardOptions';
import InfoTooltip from '../../InfoTooltip';
import { InformationCircleIcon } from '../../icons/UIIcons';

interface ConnectivityInputsProps {
  point: IOPoint;
  onUpdate: (newValues: Partial<IOPoint>) => void;
  errors?: Record<string, string>;
}

const METER_TO_FEET = 3.28084;

const ConnectivityInputs: React.FC<ConnectivityInputsProps> = ({ point, onUpdate, errors = {} }) => {
  const { userProfile } = useUserContext();
  const isImperial = userProfile.unitSystem === 'imperial';

  const toDisplay = (meters: number) => (isImperial ? (meters * METER_TO_FEET).toFixed(1) : String(meters));
  const fromDisplay = (value: string) => {
    const num = parseFloat(value) || 0;
    return isImperial ? num / METER_TO_FEET : num;
  };

  const [localDistance, setLocalDistance] = React.useState(() => toDisplay(point.distance));

  React.useEffect(() => {
    setLocalDistance(toDisplay(point.distance));
  }, [point.distance, isImperial]);

  const handleBlur = (value: string) => {
    onUpdate({ distance: fromDisplay(value) });
  };
  
  const unitLabel = isImperial ? 'ft' : 'm';

  return (
    <div className="grid\ grid-cols-1\ md:grid-cols-2\ lg:grid-cols-4\ gap-4">
      <div>
        <InfoTooltip text="The physical connector used for the signal (e.g., HDMI for video, XLR for microphones, USB-C for modern laptops). This defines the port on the wall plate or device.">
          <label htmlFor="io-connection-type" className="flex\ items-center\ gap-1\ text-sm\ font-medium">
            Connection Type
            <InformationCircleIcon className="h-4\ w-4\ text-text-secondary" />
          </label>
        </InfoTooltip>
        <select id="io-connection-type" value={point.connectionType} onChange={e => onUpdate({ connectionType: e.target.value })} className="w-full\ p-2\ border\ border-border-color\ rounded-md\ bg-input-bg\ mt-1">
          {CONNECTION_TYPES.map(opt => <option key={opt} value={opt}>{opt}</option>)}
        </select>
      </div>
      <div>
        <InfoTooltip text="How the signal travels from its source to its destination. 'Direct' means a simple cable run. 'HDBaseT' or 'AVoIP' are used to extend signals over long distances.">
            <label htmlFor="io-distribution" className="flex\ items-center\ gap-1\ text-sm\ font-medium">
              Transport Type
               <InformationCircleIcon className="h-4\ w-4\ text-text-secondary" />
            </label>
        </InfoTooltip>
        <select id="io-distribution" value={point.distributionType} onChange={e => onUpdate({ distributionType: e.target.value })} className="w-full\ p-2\ border\ border-border-color\ rounded-md\ bg-input-bg\ mt-1">
          {TRANSPORT_TYPES.map(opt => <option key={opt} value={opt}>{opt}</option>)}
        </select>
      </div>
      <div>
        <InfoTooltip text="The physical place where the connection point will be installed (e.g., a wall plate, a pop-up box in a table, or directly on a piece of furniture like a lectern).">
           <label htmlFor="io-termination" className="flex\ items-center\ gap-1\ text-sm\ font-medium">
            Location
            <InformationCircleIcon className="h-4\ w-4\ text-text-secondary" />
           </label>
        </InfoTooltip>
         <select id="io-termination" value={point.terminationType} onChange={e => onUpdate({ terminationType: e.target.value })} className="w-full\ p-2\ border\ border-border-color\ rounded-md\ bg-input-bg\ mt-1">
          {LOCATION_TYPES.map(opt => <option key={opt} value={opt}>{opt}</option>)}
        </select>
      </div>
      <div>
        <InfoTooltip text="The estimated cable length from the connection point to the central equipment rack or the next device in the chain. This is critical for determining if signal extension is needed.">
            <label htmlFor="io-distance" className="flex\ items-center\ gap-1\ text-sm\ font-medium">
              Distance ({unitLabel})
              <InformationCircleIcon className="h-4\ w-4\ text-text-secondary" />
            </label>
        </InfoTooltip>
        <input
          type="number"
          step="0.1"
          id="io-distance"
          value={localDistance}
          onChange={(e) => setLocalDistance(e.target.value)}
          onBlur={(e) => handleBlur(e.target.value)}
          className={`w-full p-2 border rounded-md bg-input-bg mt-1 ${errors['distance'] ? 'border-destructive' : 'border-border-color'}`}
        />
        {errors['distance'] && <p className="text-destructive\ text-sm\ mt-1">{errors['distance']}</p>}
      </div>
    </div>
  );
};

