export type ProposalSection = {
  key: string;
  title: string;
  body: string;
};

export type ProposalExportPayload = {
  fileName: string;
  title: string;
  subtitle?: string;
  sections: ProposalSection[];
  metadata: Record<string, string>;
  equipment: Array<{
    sku?: string;
    name: string;
    qty?: number;
    notes?: string;
  }>;
  pricing: {
    currency?: string;
    equipmentSubtotal?: string;
    installationAllowance?: string;
    programmingAllowance?: string;
    totalBudgetNote?: string;
  };
};

export type ProposalExportInput = {
  projectName?: string;
  customerName?: string;
  companyName?: string;
  verticalMarket?: string;
  roomType?: string;
  tier?: string;
  executiveSummary?: string;
  solutionOverview?: string;
  assumptions?: string;
  exclusions?: string;
  commercialNotes?: string;
  positioningBlock?: string;
  compareSummary?: string;
  nextSteps?: string;
  designSummary?: string;
  cableScheduleSummary?: string;
  diagramSummary?: string;
  usedDevicesSummary?: string;
  equipment?: Array<{
    sku?: string;
    name: string;
    qty?: number;
    notes?: string;
  }>;
  pricing?: {
    currency?: string;
    equipmentSubtotal?: string;
    installationAllowance?: string;
    programmingAllowance?: string;
    totalBudgetNote?: string;
  };
};

function tidy(value: unknown): string {
  return String(value ?? "").trim();
}

function safeFileName(value: string): string {
  const v = tidy(value) || "proposal";
  return v.replace(/[^a-z0-9_\-]+/gi, "_");
}

function pushSection(sections: ProposalSection[], key: string, title: string, body?: string) {
  const text = tidy(body);
  if (!text) return;
  sections.push({ key, title, body: text });
}

export function buildProposalExportPayload(input: ProposalExportInput): ProposalExportPayload {
  const projectName = tidy(input.projectName) || "Untitled Project";
  const subtitle = [
    tidy(input.customerName),
    tidy(input.companyName),
    tidy(input.verticalMarket),
    tidy(input.roomType),
    tidy(input.tier),
  ].filter(Boolean).join(" / ");

  const sections: ProposalSection[] = [];
  pushSection(sections, "executiveSummary", "Executive Summary", input.executiveSummary);
  pushSection(sections, "solutionOverview", "Solution Overview", input.solutionOverview);
  pushSection(sections, "assumptions", "Assumptions", input.assumptions);
  pushSection(sections, "exclusions", "Exclusions", input.exclusions);
  pushSection(sections, "commercialNotes", "Commercial Notes", input.commercialNotes);
  pushSection(sections, "competitivePositioning", "Competitive Positioning", input.positioningBlock);
  pushSection(sections, "nextSteps", "Next Steps", input.nextSteps);

  return {
    fileName: `${safeFileName(projectName)}_proposal`,
    title: projectName,
    subtitle,
    sections,
    metadata: {
      customerName: tidy(input.customerName),
      companyName: tidy(input.companyName),
      verticalMarket: tidy(input.verticalMarket),
      roomType: tidy(input.roomType),
      tier: tidy(input.tier),
      compareSummary: tidy(input.compareSummary),
    },
    equipment: Array.isArray(input.equipment) ? input.equipment : [],
    pricing: {
      currency: tidy(input.pricing?.currency),
      equipmentSubtotal: tidy(input.pricing?.equipmentSubtotal),
      installationAllowance: tidy(input.pricing?.installationAllowance),
      programmingAllowance: tidy(input.pricing?.programmingAllowance),
      totalBudgetNote: tidy(input.pricing?.totalBudgetNote),
    },
  };
}

export type ProposalTemplateInput = {
  projectName?: string;
  customerName?: string;
  companyName?: string;
  verticalMarket?: string;
  roomType?: string;
  tier?: string;
  compareSummary?: string;
};

function tidy(value: unknown): string {
  return String(value ?? "").trim();
}

function sentence(text: string): string {
  const v = tidy(text);
  if (!v) return "";
  return /[.!?]$/.test(v) ? v : `${v}.`;
}

export function buildExecutiveSummaryTemplate(input: ProposalTemplateInput): string {
  const project = tidy(input.projectName) || "this project";
  const market = tidy(input.verticalMarket).toLowerCase();
  const room = tidy(input.roomType).toLowerCase();
  const tier = tidy(input.tier);

  const parts = [
    `${project} has been developed as a ${tier ? tier + " " : ""}${room || "AV"} solution`,
    market ? `for ${market} use` : "",
    "with emphasis on operational clarity, appropriate feature selection, and commercial fit",
  ].filter(Boolean);

  return sentence(parts.join(" "));
}

export function buildSolutionOverviewTemplate(input: ProposalTemplateInput): string {
  const room = tidy(input.roomType).toLowerCase();
  const market = tidy(input.verticalMarket).toLowerCase();

  const parts = [
    "The proposed solution is designed to deliver a clear and supportable AV workflow",
    room ? `for the ${room} environment` : "",
    market ? `within the ${market} application context` : "",
    "while keeping system operation straightforward for the end user",
  ].filter(Boolean);

  return sentence(parts.join(" "));
}

export function buildAssumptionsTemplate(input: ProposalTemplateInput): string {
  const parts = [
    "Pricing, final device counts, and site-specific infrastructure requirements remain subject to final survey confirmation",
    "Existing containment, power availability, and network readiness are assumed to be suitable unless otherwise noted",
    "Any third-party control, furniture integration, or construction works are assumed to be outside this proposal unless explicitly included",
  ];

  return parts.join("\n");
}

export function buildExclusionsTemplate(input: ProposalTemplateInput): string {
  const parts = [
    "Builder's works, specialist construction works, and decoration are excluded",
    "Network switching, structured cabling, and third-party services are excluded unless specifically stated",
    "Programming, commissioning, or user training beyond standard handover are excluded unless separately listed",
  ];

  return parts.join("\n");
}

export function buildCommercialNotesTemplate(input: ProposalTemplateInput): string {
  const compare = tidy(input.compareSummary);

  const parts = [
    "This recommendation has been positioned to balance technical suitability, deployment simplicity, and commercial clarity.",
    compare ? `Competitive reference considered: ${compare}` : "",
    "Final commercial validation should confirm exact SKU availability, lead time, and any project-specific installation allowances.",
  ].filter(Boolean);

  return parts.join(" ");
}

export function buildNextStepsTemplate(input: ProposalTemplateInput): string {
  return [
    "Confirm final room requirements and site constraints.",
    "Validate final SKU selection and any optional accessories.",
    "Review commercial assumptions, lead times, and installation scope.",
    "Issue final customer proposal for approval.",
  ].join("\n");
}

