import * as React from "react";
import { Document, Packer, Paragraph, TextRun, Table, TableCell, TableRow, WidthType, AlignmentType, BorderStyle, HeadingLevel } from 'docx';
import { Proposal, ProjectData } from './types';
import { format } from 'date-fns';

export const exportProposalToDocx = async (proposal: Proposal, project: ProjectData) => {
  // Create equipment list table
  const equipmentTable = new Table({
    width: {
      size: 100,
      type: WidthType.PERCENTAGE,
    },
    rows: [
      // Header row
      new TableRow({
        tableHeader: true,
        children: [
          new TableCell({
            children: [new Paragraph({
              text: 'SKU',
              style: 'TableHeader',
            })],
            shading: {
              fill: '00833D', // WyreStorm Green
            },
          }),
          new TableCell({
            children: [new Paragraph({
              text: 'Product Name',
              style: 'TableHeader',
            })],
            shading: {
              fill: '00833D',
            },
          }),
          new TableCell({
            children: [new Paragraph({
              text: 'Quantity',
              style: 'TableHeader',
            })],
            shading: {
              fill: '00833D',
            },
          }),
        ],
      }),
      // Data rows
      ...proposal.equipmentList.map((item: any) =>
        new TableRow({
          children: [
            new TableCell({
              children: [new Paragraph(item.sku)],
            }),
            new TableCell({
              children: [new Paragraph(item.name)],
            }),
            new TableCell({
              children: [new Paragraph(item.quantity.toString())],
            }),
          ],
        })
      ),
    ],
  });

  // Build document
  const doc = new Document({
    styles: {
      paragraphStyles: [
        {
          id: 'TableHeader',
          name: 'Table Header',
          basedOn: 'Normal',
          run: {
            bold: true,
            color: 'FFFFFF',
          },
        },
      ],
    },
    sections: [
      {
        properties: {},
        children: [
          // Title
          new Paragraph({
            text: 'PROPOSAL',
            heading: HeadingLevel.TITLE,
            alignment: AlignmentType.CENTER,
            spacing: {
              after: 400,
            },
            run: {
              color: '00833D', // WyreStorm Green
              size: 48,
              bold: true,
            },
          }),

          // Project Information
          new Paragraph({
            text: 'Project Information',
            heading: HeadingLevel.HEADING_1,
            spacing: {
              before: 300,
              after: 200,
            },
          }),
          new Paragraph({
            children: [
              new TextRun({ text: 'Project: ', bold: true }),
              new TextRun(project.projectName),
            ],
            spacing: { after: 100 },
          }),
          new Paragraph({
            children: [
              new TextRun({ text: 'Client: ', bold: true }),
              new TextRun(project.clientName),
            ],
            spacing: { after: 100 },
          }),
          new Paragraph({
            children: [
              new TextRun({ text: 'Version: ', bold: true }),
              new TextRun(proposal.version),
            ],
            spacing: { after: 100 },
          }),
          new Paragraph({
            children: [
              new TextRun({ text: 'Date: ', bold: true }),
              new TextRun(format(new Date(proposal.createdAt), 'MMMM dd, yyyy')),
            ],
            spacing: { after: 400 },
          }),

          // Executive Summary
          new Paragraph({
            text: 'Executive Summary',
            heading: HeadingLevel.HEADING_1,
            spacing: {
              before: 400,
              after: 200,
            },
          }),
          new Paragraph({
            text: proposal.executiveSummary,
            spacing: { after: 400 },
          }),

          // Scope of Work
          new Paragraph({
            text: 'Scope of Work',
            heading: HeadingLevel.HEADING_1,
            spacing: {
              before: 400,
              after: 200,
            },
          }),
          new Paragraph({
            text: proposal.scopeOfWork,
            spacing: { after: 400 },
          }),

          // Equipment List
          new Paragraph({
            text: 'Equipment List',
            heading: HeadingLevel.HEADING_1,
            spacing: {
              before: 400,
              after: 200,
            },
          }),
          equipmentTable,
          new Paragraph({ text: '', spacing: { after: 400 } }), // Spacer

          // Assumptions (if any)
          ...(proposal.assumptions && proposal.assumptions.length > 0
            ? [
                new Paragraph({
                  text: 'Assumptions',
                  heading: HeadingLevel.HEADING_1,
                  spacing: {
                    before: 400,
                    after: 200,
                  },
                }),
                ...proposal.assumptions.map((assumption: any, index: number) =>
                    new Paragraph({
                      text: `${index + 1}. ${assumption}`,
                      spacing: { after: 100 },
                      indent: { left: 360 },
                    })
                ),
                new Paragraph({ text: '', spacing: { after: 400 } }),
              ]
            : []),

          // Exclusions (if any)
          ...(proposal.exclusions && proposal.exclusions.length > 0
            ? [
                new Paragraph({
                  text: 'Exclusions',
                  heading: HeadingLevel.HEADING_1,
                  spacing: {
                    before: 400,
                    after: 200,
                  },
                }),
                ...proposal.exclusions.map((exclusion: any, index: number) =>
                    new Paragraph({
                      text: `${index + 1}. ${exclusion}`,
                      spacing: { after: 100 },
                      indent: { left: 360 },
                    })
                ),
              ]
            : []),

          // Footer
          new Paragraph({
            text: 'Generated with WyreStorm Wingman',
            alignment: AlignmentType.CENTER,
            spacing: {
              before: 800,
            },
            run: {
              italics: true,
              size: 18,
              color: '64748b', // text-secondary
            },
          }),
        ],
      },
    ],
  });

  // Generate and download
  const blob = await Packer.toBlob(doc);
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = `${project.projectName}_Proposal_v${proposal.version}.docx`;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
};

import * as React from "react";
import { RoomData, Product, ProjectInfrastructure } from '../../utils/types';
import { TECHNICAL_DATABASE } from '../../data/technicalDatabase';
import { getCorePrinciples } from './designRoom/corePrinciples';
import { getFeatureDrivenDesignLogic } from './designRoom/featureDrivenDesign';
import { getControlSystemLogic } from './designRoom/controlSystemLogic';
import { getVideoWallLogic } from './designRoom/videoWallLogic';
import { getAvoipLogic } from './designRoom/avoipLogic';
import { getSignalExtensionLogic } from './designRoom/signalExtensionLogic';
import { getProductCompatibilityRules } from './designRoom/productCompatibility';
import { getProductConsolidationLogic } from './designRoom/productConsolidation';
import { getSKUNamingConventions } from './designRoom/skuConventions';
import { getDesignMinimalismRules } from './designRoom/minimalism';
import { getRoomApplicationLogic } from './designRoom/roomApplicationLogic';
import { getUcLogic } from './designRoom/ucLogic';
import { getProductGranularity } from './designRoom/productGranularity';
import { getTieredDesignLogic } from './designRoom/tieredDesignLogic';
import { getInfrastructureLogic } from './designRoom/infrastructureLogic';

export const generateDesignPrompt = (
  room: RoomData,
  productDatabase: Product[],
  infrastructure?: ProjectInfrastructure,
  valueEngineeringInstruction = ''
): string => {
  const productDbString = JSON.stringify(
    productDatabase.map(p => ({ 
      sku: p.sku, name: p.name, category: p.category, 
      description: p.description, tags: p.tags, status: p.status,
      usb: p.usb,
      hdbaset: p.hdbaset
    })), null, 2
  );

  const infraContext = infrastructure ? `
  Infrastructure Context:
  - Building Type: ${infrastructure.buildingType}
  - Floor Count: ${infrastructure.floorCount}
  - Rack Strategy: ${infrastructure.rackStrategy}
  - Cabling by Others: ${infrastructure.cablingByOthers}
  ` : '';

  return `
  You are an expert AV System Designer for WyreStorm. Your task is to select the appropriate equipment for the given room requirements from the provided product database.

  Room Details:
  - Name: ${room.roomName}
  - Type: ${room.roomType}
  - Tier: ${room.designTier}
  - Functionality Statement: ${room.functionalityStatement}
  - Key Features Required: ${room.features.map(f => `${f.name} (${f.priority})`).join(', ') || 'None'}
  - IO Points: ${JSON.stringify(room.ioRequirements, null, 2)}
  - Audio Details: ${JSON.stringify(room.audioSystemDetails, null, 2)}
  - Control System: ${room.technicalDetails.controlSystem}
  ${room.videoWallConfig ? `- Video Wall Config: ${JSON.stringify(room.videoWallConfig, null, 2)}` : ''}
  - AVoIP System Selected: ${room.technicalDetails.avoipSystem || 'None'}
  ${infraContext}

  Available WyreStorm Products (use ONLY these products):
  ${productDbString}
  
  Technical Reference Material:
  ${TECHNICAL_DATABASE}

  === DESIGN LOGIC MODULES ===
  ${getTieredDesignLogic()}
  ${getInfrastructureLogic()}
  ${getRoomApplicationLogic()}
  ${getFeatureDrivenDesignLogic()}
  ${getUcLogic()}
  ${getProductGranularity()}
  ${getControlSystemLogic()}
  ${getVideoWallLogic()}
  ${getSignalExtensionLogic()}
  ${getAvoipLogic()}
  ${getProductCompatibilityRules()}
  ${getCorePrinciples()}
  
  ${valueEngineeringInstruction}

  Based on all rules and the room details, perform the following tasks:
  1. Write a concise, one-paragraph "functionalityStatement" that explains the design rationale, specifically mentioning how the room purpose is served (e.g., "Using MST technology for dual screens...").
  2. Create a list of equipment in the "manuallyAddedEquipment" array.
     - You MUST select products ONLY from the provided database.
     - Specify the SKU and quantity for each item.

  Return only valid JSON. Do not include markdown formatting or explanations.
  `;
};

import * as React from "react";
import { NavLink } from "react-router-dom";
import { brand } from "@/branding/brand";
import { getActiveWorkflowProject } from "@/workflow/workflowStore";

type MissionControlNavProps = {
  collapsed?: boolean;
  onToggleCollapse?: () => void;
};

type NavItem = {
  section: string;
  title: string;
  desc: string;
  short: string;
  to: string;
};

const NAV_ITEMS: NavItem[] = [
  { section: "Mission Control", title: "Mission Control", desc: "Pipeline and project flow", short: "MC", to: "/app/dashboard" },
  { section: "Mission Control", title: "Projects", desc: "All active opportunities", short: "PR", to: "/app/projects" },
  { section: "Mission Control", title: "Active Project Workflow", desc: "Discovery and solution logic", short: "AW", to: "/app/dashboard" },

  { section: "Workflow", title: "Discovery", desc: "Capture requirements", short: "D", to: "/app/tools/discovery" },
  { section: "Workflow", title: "Architecture", desc: "Advance to solution logic", short: "A", to: "/app/dashboard" },
  { section: "Workflow", title: "Products", desc: "Select core products", short: "P", to: "/app/tools/catalog" },
  { section: "Workflow", title: "Proposal", desc: "Build customer output", short: "PB", to: "/app/tools/proposal" },

  { section: "Tools & Reference", title: "Tool Hub", desc: "Browse all tools", short: "TH", to: "/app/tools" },
  { section: "Tools & Reference", title: "Product Catalogue", desc: "Reference products", short: "PC", to: "/app/tools/catalog" },
  { section: "Tools & Reference", title: "Competitor Comparison", desc: "Position WyreStorm", short: "CC", to: "/app/tools/compare" },
  { section: "Tools & Reference", title: "Video Wall Designer", desc: "Display planning", short: "VW", to: "/app/tools/video-wall" },
];

function groupedItems(items: NavItem[]): Array<{ section: string; items: NavItem[] }> {
  const map = new Map<string, NavItem[]>();
  for (const item of items) {
    const current = map.get(item.section) ?? [];
    current.push(item);
    map.set(item.section, current);
  }
  return Array.from(map.entries()).map(([section, sectionItems]) => ({ section, items: sectionItems }));
}

export default function MissionControlNav({ collapsed = false, onToggleCollapse }: MissionControlNavProps) {
  const [tick, setTick] = React.useState(0);

  React.useEffect(() => {
    const id = window.setInterval(() => setTick((v) => v + 1), 1200);
    return () => window.clearInterval(id);
  }, []);

  const activeProject = React.useMemo(() => getActiveWorkflowProject(), [tick]);
  const sections = React.useMemo(() => groupedItems(NAV_ITEMS), []);

  return (
    <aside className={`wm-nav${collapsed ? " is-collapsed" : ""}`}>
      <div className="wm-nav__top">
        <div className="wm-nav__brand">
          <img src={brand.logo} alt={brand.fullName} className="wm-nav__logo" />
          {!collapsed ? (
            <div className="wm-nav__brand-copy">
              <div className="wm-nav__brand-title">Wingman</div>
              <div className="wm-nav__brand-subtitle">Workflow platform</div>
            </div>
          ) : null}
        </div>

        <button
          type="button"
          className="wm-nav__collapse"
          onClick={onToggleCollapse}
          aria-label={collapsed ? "Expand navigation" : "Collapse navigation"}
          title={collapsed ? "Expand navigation" : "Collapse navigation"}
        >
          {collapsed ? ">>" : "<<"}
        </button>
      </div>

      <div className="wm-nav__active-card">
        <div className="wm-nav__active-label">Active Project</div>
        <div className="wm-nav__active-name">
          {collapsed ? (activeProject?.name?.slice(0, 2) ?? "--") : (activeProject?.name ?? "No active project")}
        </div>
        {!collapsed ? (
          <div className="wm-nav__active-copy">
            {activeProject
              ? `${activeProject.customer} | ${activeProject.roomType}`
              : "Create or select a project from Mission Control"}
          </div>
        ) : null}
      </div>

      <div className="wm-nav__sections">
        {sections.map((section) => (
          <section key={section.section} className="wm-nav__section">
            {!collapsed ? (
              <div className="wm-nav__section-title">{section.section}</div>
            ) : null}

            <div className="wm-nav__list">
              {section.items.map((item) => (
                <NavLink
                  key={`${section.section}-${item.title}`}
                  to={item.to}
                  className={({ isActive }) =>
                    `wm-nav__item${isActive ? " is-active" : ""}${collapsed ? " is-collapsed" : ""}`
                  }
                  title={collapsed ? item.title : undefined}
                >
                  <span className="wm-nav__item-badge">{item.short}</span>
                  {!collapsed ? (
                    <span className="wm-nav__item-copy">
                      <span className="wm-nav__item-title">{item.title}</span>
                      <span className="wm-nav__item-desc">{item.desc}</span>
                    </span>
                  ) : null}
                </NavLink>
              ))}
            </div>
          </section>
        ))}
      </div>
    </aside>
  );
}

import { getActiveWorkflowProject } from "./workflowStore";
import { buildArchitectureRecommendation } from "./architectureRecommendations";

export type StarterBomItem = {
  category: string;
  recommendation: string;
  quantityHint: string;
  note: string;
};

export type SolutionRecommendation = {
  platform: string;
  topology: string;
  confidence: "Low" | "Medium" | "High";
  summary: string;
  families: string[];
  buildingBlocks: string[];
  starterBom: StarterBomItem[];
  commercialNotes: string[];
};

function boolText(value: boolean | undefined, yes: string): string[] {
  return value ? [yes] : [];
}

export function buildSolutionRecommendation(
  active = getActiveWorkflowProject()
): SolutionRecommendation {
  const architecture = buildArchitectureRecommendation(active);

  if (!active || !architecture.primary) {
    return {
      platform: "No recommendation yet",
      topology: "Awaiting active project data",
      confidence: "Low",
      summary: "Complete discovery and set an active project before generating a WyreStorm solution path.",
      families: [],
      buildingBlocks: [],
      starterBom: [],
      commercialNotes: [
        "Set or create an active project in Mission Control.",
        "Capture source count, display count, and distance in Discovery.",
      ],
    };
  }

  const sources = active.sources ?? 0;
  const displays = active.displays ?? 0;
  const distance = active.distanceM ?? 0;
  const room = String(active.roomType ?? "").toLowerCase();

  if (architecture.primary === "Video Wall") {
    return {
      platform: "WyreStorm video wall workflow",
      topology: "Processor-led multi-display presentation system",
      confidence: architecture.confidence,
      summary: "The project suits a presentation-led video wall architecture with distribution, processing, and display coordination.",
      families: ["Video Wall", "Distribution", "Control", ...boolText(active.audio, "Audio")],
      buildingBlocks: [
        "Video wall processor or presentation processor",
        "Input switching layer",
        "Display endpoints or wall feed outputs",
        "Control integration",
        ...boolText(active.audio, "Audio breakout / DSP path"),
      ],
      starterBom: [
        {
          category: "Processing",
          recommendation: "Video wall or presentation processor",
          quantityHint: "1",
          note: "Confirm layout, sources, and canvas behaviour first.",
        },
        {
          category: "Inputs",
          recommendation: "Source input / switching layer",
          quantityHint: "Match source count",
          note: "Scale to actual source quantity.",
        },
        {
          category: "Outputs",
          recommendation: "Wall feed outputs / distribution endpoints",
          quantityHint: "Match display or wall zone count",
          note: "Depends on wall layout and content mapping.",
        },
        {
          category: "Control",
          recommendation: "Control gateway / room control layer",
          quantityHint: "1",
          note: "Include if preset recall or user control is required.",
        },
      ],
      commercialNotes: [
        "Confirm wall layout and bezel/pixel strategy before final product selection.",
        "Treat processing and content presentation as the lead decision, not just transport.",
      ],
    };
  }

  if (architecture.primary === "AVoIP") {
    return {
      platform: "WyreStorm NetworkHD-style AVoIP workflow",
      topology: "Network-distributed AV over IP architecture",
      confidence: architecture.confidence,
      summary: "The project leans toward distributed AV transport across multiple endpoints or longer-distance zones.",
      families: ["AVoIP", "Encoders", "Decoders", "Network Switching", ...boolText(active.usb, "USB"), ...boolText(active.control, "Control")],
      buildingBlocks: [
        "AV over IP encoders",
        "AV over IP decoders",
        "Managed network switching",
        "Control / routing layer",
        ...boolText(active.usb, "USB extension path"),
        ...boolText(active.audio, "Audio breakout or DSP path"),
      ],
      starterBom: [
        {
          category: "Encoding",
          recommendation: "AVoIP encoder endpoints",
          quantityHint: "Match source count",
          note: "One encoder per source in most straightforward designs.",
        },
        {
          category: "Decoding",
          recommendation: "AVoIP decoder endpoints",
          quantityHint: "Match display count",
          note: "Scale per display or destination endpoint.",
        },
        {
          category: "Networking",
          recommendation: "Managed switch / switching fabric",
          quantityHint: "1+",
          note: "Confirm multicast, VLAN, bandwidth, and endpoint count.",
        },
        {
          category: "Control",
          recommendation: "AV routing / control layer",
          quantityHint: "1",
          note: "Needed for user workflow and source routing.",
        },
      ],
      commercialNotes: [
        "Best suited to larger endpoint counts, multi-room distribution, or extended distances.",
        "Network assumptions must be validated before final BOM sign-off.",
      ],
    };
  }

  if (architecture.primary === "Matrix Switching") {
    return {
      platform: "WyreStorm matrix switching workflow",
      topology: "Central switch with distributed endpoints",
      confidence: architecture.confidence,
      summary: "The project suits a switching-led architecture where routing flexibility is central to the design.",
      families: ["Matrix Switching", "Transmitters", "Receivers", ...boolText(active.usb, "USB"), ...boolText(active.control, "Control")],
      buildingBlocks: [
        "Central matrix switch",
        "Input transmitters where required",
        "Output receivers where required",
        ...boolText(active.usb, "USB extension pair or switching-capable USB layer"),
        ...boolText(active.audio, "Audio de-embed / amplify path"),
      ],
      starterBom: [
        {
          category: "Switching",
          recommendation: "Central matrix chassis",
          quantityHint: "1",
          note: "Choose size from actual source/display count with headroom.",
        },
        {
          category: "Inputs",
          recommendation: "Source transmitters or local inputs",
          quantityHint: "Match source count",
          note: "Depends on where sources are physically located.",
        },
        {
          category: "Outputs",
          recommendation: "Display receivers or local outputs",
          quantityHint: "Match display count",
          note: "Depends on destination distance and endpoint style.",
        },
        {
          category: "Control",
          recommendation: "Control / UI interface",
          quantityHint: "1",
          note: "Include user routing and room operation requirements.",
        },
      ],
      commercialNotes: [
        "Good fit where routing flexibility matters more than network-scale distribution.",
        "Validate growth headroom before fixing matrix size.",
      ],
    };
  }

  return {
    platform: "WyreStorm HDBaseT extension workflow",
    topology: distance > 0 && distance <= 70
      ? "Point-to-point or small switched HDBaseT distribution"
      : "Moderate-distance extension architecture",
    confidence: architecture.confidence,
    summary: "The project suits an HDBaseT-led architecture with focused extension, switching, and room control.",
    families: ["HDBaseT", "Transmitters", "Receivers", ...boolText(active.usb, "USB"), ...boolText(active.control, "Control")],
    buildingBlocks: [
      "HDBaseT transmitters",
      "HDBaseT receivers",
      "Switching or presentation input layer",
      ...boolText(active.usb, "USB extension path"),
      ...boolText(active.audio, "Audio integration path"),
      ...boolText(active.control, "Control layer"),
    ],
    starterBom: [
      {
        category: "Extension",
        recommendation: "HDBaseT transmitter/receiver endpoints",
        quantityHint: `${Math.max(sources, 1)} source-side / ${Math.max(displays, 1)} display-side`,
        note: "Final count depends on switching topology and endpoint locations.",
      },
      {
        category: "Switching",
        recommendation: sources > 1 || displays > 1 ? "Presentation switcher or matrix layer" : "Direct extension path",
        quantityHint: "1",
        note: "Needed where local switching or source selection is required.",
      },
      {
        category: "USB",
        recommendation: active.usb ? "USB extension support" : "Not primary",
        quantityHint: active.usb ? "As required" : "-",
        note: active.usb ? "Confirm host/device roles and BYOD/camera scope." : "Add later only if collaboration peripherals are required.",
      },
      {
        category: "Control",
        recommendation: active.control ? "Room control / trigger / API layer" : "Basic operation",
        quantityHint: "1",
        note: active.control ? "Confirm touch, button, or automation workflow." : "Can remain minimal if no room automation is needed.",
      },
    ],
    commercialNotes: [
      "Strong fit for moderate distance and contained room scope.",
      sources > 3 || displays > 3
        ? "Recheck whether matrix or AVoIP becomes commercially cleaner as scale grows."
        : "Simple, lower-complexity architecture may support a faster sales cycle.",
    ],
  };
}
